// === Tab: mySketch ===
angle=0
hu=l=0

setup=()=>{
  createCanvas(v=1112,w=834)
  pg=createGraphics(v,w)
  pg.colorMode(HSB)
	hu=random(255)
}

draw=()=>{
  pg.background(w,.05).noStroke()
	pg.fill(hu%360,255,180)
  x=y=0
  for(i=2e3;i--;){
    degree=PI/2*int(4*noise((frameCount-i)/99))
    x+=2*cos(degree)
    y+=2*sin(degree)
    x=(x+v)%v
    y=(y+w)%w
    pg.rect(x,y,2,2)
  }

  angle=lerp(angle,degree,.003)          
  translate(v/2,w/2)
  rotate(-angle-PI/2)
  translate(-x,-y)
  for(i of[-v,0,v])
    for(j of[-w,0,w])
      image(pg,i,j,v,w)
	hu++;
}
mousePressed=()=>{if (millis()-l>400){save("img_"+month()+'-'+day()+'_'+hour()+'-'+minute()+'-'+second()+".jpg");l=millis();}}

